        base_counters,
        cls._counter_snapshot_pairs(base_counters, service, labels),
    )
    samples, sample_view = cls._patch_filtered_view(
        base_samples,
        cls._sample_snapshot_pairs(base_samples, service, labels),
    )
    spans, span_view = cls._patch_filtered_view(
        base_spans,
        cls._span_snapshot_pairs(base_spans, service, status, labels),
    )

