            counter_view,
            patch_counters,
            lambda key: key,
            cls._restore_counters,
            lambda record: (
                record["service"], record["name"],
                cls._restore_labels(record["labels"]),
            ),
        )
        cls._apply_patch_section(
            sample_view,
            patch_samples,
            lambda key: key,
            cls._restore_samples,
            lambda record: (
                record["service"], record["name"],
                cls._restore_labels(record["labels"]),
            ),
        )
        cls._apply_patch_section(
            span_view,
            patch_spans,
            lambda key: key,
            cls._restore_spans,
            lambda record: (record["service"], record["span"]),
        )
    except ValueError as exc:
        if isinstance(exc, SnapshotFormatError):
            raise
        raise SnapshotPatchError(str(exc))

    # 视图已解析为内部记录形态，与视图外的基础内部状态直接合并；视图外
    # 记录来自 base 的全新解析结构，合并结果不与任何输入共享对象。
