    samples.update(sample_view)
    spans.update(span_view)

    # 应用后重新验证：补丁可能使样本统计需要重算（输出时统一重算），
    # 也可能引入悬空或成环的父子引用；任一不通过抛 SnapshotFormatError，
    # 不返回部分结果。
    cls._restore_check_span_links(spans)

    result = {
        "counters": [
            entry
            for _, entry in cls._counter_snapshot_pairs(counters)
        ],
        "samples": [
            entry
            for _, entry in cls._sample_snapshot_pairs(samples)
        ],
        "spans": [
            entry
            for _, entry in cls._span_snapshot_pairs(spans)
        ],
    }
    if "version" in base_data:
        result["version"] = base_data["version"]
    # 深拷贝切断与解析中间结构的引用，保证返回值与输入完全独立。
    return copy.deepcopy(result)

@classmethod
def _patch_validate(cls, data):
    # 补丁顶层只能有 counters/samples/spans 三个分区（不接受 version 或
    # 其他字段）；每个分区只能有 added/removed/changed 三个数组；changed
    # 元素只能含 before/after。记录本身的格式交由既有快照记录规则校验。
    if not isinstance(data, dict):
        raise SnapshotFormatError("patch must decode to a JSON object")
    sections = ("counters", "samples", "spans")
    if set(data) != set(sections):
        raise SnapshotFormatError(
            "patch must contain exactly counters, samples and spans"
        )
    parsed = {}
    for section in sections:
        bucket = data[section]
        if not isinstance(bucket, dict) or set(bucket) != {
            "added", "removed", "changed"
        }:
            raise SnapshotFormatError(
                "patch section %s must contain exactly added, removed"
                " and changed" % (section,)
            )
        for name in ("added", "removed", "changed"):
            records = bucket[name]
            if not isinstance(records, list):
                raise SnapshotFormatError(
                    "patch %s.%s must be an array" % (section, name)
                )
            if name == "changed":
                for item in records:
                    if not isinstance(item, dict) or set(item) != {
                        "before", "after"
                    }:
                        raise SnapshotFormatError(
                            "patch changed entry must contain exactly"
                            " before and after"
                        )
        # 记录按既有快照规则解析：字段、标签、可哈希标识、非有限样本与
        # 统计一致性在此统一以 SnapshotFormatError 拒绝；同桶内或
        # before/after 之间的重复定位由应用阶段的冲突检查处理。
        restore = {
            "counters": cls._restore_counters,
            "samples": cls._restore_samples,
            "spans": cls._restore_spans,
        }[section]
        added = restore(bucket["added"])
        removed = restore(bucket["removed"])
        before = restore([item["before"] for item in bucket["changed"]])
        after = restore([item["after"] for item in bucket["changed"]])
        parsed[section] = (added, removed, before, after)
    return (
        parsed["counters"],
        parsed["samples"],
        parsed["spans"],
    )

@staticmethod
def _patch_filtered_view(base_state, pairs):
    # 依据筛选后的 (定位, 快照记录) 对构造“基础状态全集 + 视图子集”：
    # 视图外定位保持内部状态原值，视图内定位随后由应用阶段替换。pairs
    # 中的快照记录需先还原为内部记录形态，因此这里只标记视图内定位，
    # 实际记录在应用阶段从补丁/基础快照记录重新解析。
    kept = dict(base_state)
    view = {}
    for key, _entry in pairs:
        view[key] = None
    return kept, view

@staticmethod
def _patch_record_equal(left, right):
    # 两条已解析的内部记录（计数器为原值、样本为 values 列表、跨度为
    # 记录字典）必须逐项相等；自定义对象比较异常属于补丁与视图不匹配。
    try:
        return left == right
    except Exception as exc:
        raise SnapshotPatchError(
            "patch records cannot be compared: %s" % (exc,)
        )

@classmethod
def _apply_patch_section(cls, view, patch_section, _key_of, restore_records,
                         locator):
    # 在一个分区的筛选视图上应用 added/removed/changed。view 以定位为
    # 键，值为 None 表示“该定位属于视图，但基础记录尚未载入”；基础记录
    # 通过调用方传入的基础快照记录惰性解析载入。这里改为先由调用方把
    # 视图定位映射到基础内部记录，None 即表示视图中不存在该记录。
    added, removed, changed_before, changed_after = patch_section

    # 同一定位的冲突检查：added/removed/changed 各自内部不得重复定位，
    # 且同一定位不得跨桶出现（changed 两侧定位必须相同）。
    buckets = (
        ("added", added),
        ("removed", removed),
        ("changed.before", changed_before),
        ("changed.after", changed_after),
    )
    owner = {}
    for name, records in buckets:
        for key in records:
            previous = owner.get(key)
            if previous is not None:
                raise SnapshotPatchError(
                    "conflicting patch operations for the same locator:"
                    " %s and %s" % (previous, name)
                )
            owner[key] = name
    # before/after 必须成对且定位相同：restore 保持数组顺序，两侧键集合
    # 已通过同键冲突检查保证一一对应，这里再按记录数组顺序逐对核对。
    if list(changed_before) != list(changed_after):
        raise SnapshotPatchError(
            "changed before and after must have the same locator"
        )

    for key, record in removed.items():
        current = view.get(key, _PATCH_MISSING)
        if current is _PATCH_MISSING:
            raise SnapshotPatchError(
                "removed record is outside the filtered view or missing"
                " from base"
            )
        if not cls._patch_record_equal(current, record):
            raise SnapshotPatchError(
                "removed record does not match the base record"
            )
        del view[key]
    for key, record in added.items():
        if key in view:
            raise SnapshotPatchError(
                "added record already exists in the filtered view"
            )
        view[key] = record
    for key, after_record in changed_after.items():
        before_record = changed_before[key]
        current = view.get(key, _PATCH_MISSING)
        if current is _PATCH_MISSING:
            raise SnapshotPatchError(
                "changed record is outside the filtered view or missing"
                " from base"
            )
        if not cls._patch_record_equal(current, before_record):
            raise SnapshotPatchError(
                "changed before does not match the current record"
            )
        view[key] = after_record

