    if not isinstance(data, dict):
        raise SnapshotFormatError("patch must decode to a JSON object")
    sections = ("counters", "samples", "spans")
    if set(data) != set(sections):
        raise SnapshotFormatError(
            "patch must contain exactly counters, samples and spans"
        )
    parsed = {}
    for section in sections:
        bucket = data[section]
        if not isinstance(bucket, dict) or set(bucket) != {
            "added", "removed", "changed"
        }:
            raise SnapshotFormatError(
                "patch section %s must contain exactly added, removed"
                " and changed" % (section,)
            )
        for name in ("added", "removed", "changed"):
            records = bucket[name]
            if not isinstance(records, list):
                raise SnapshotFormatError(
                    "patch %s.%s must be an array" % (section, name)
                )
            if name == "changed":
                for item in records:
                    if not isinstance(item, dict) or set(item) != {
                        "before", "after"
                    }:
                        raise SnapshotFormatError(
                            "patch changed entry must contain exactly"
                            " before and after"
                        )
        # 记录按既有快照规则解析：字段、标签、可哈希标识、非有限样本与
        # 统计一致性在此统一以 SnapshotFormatError 拒绝；同桶内或
        # before/after 之间的重复定位由应用阶段的冲突检查处理。
        restore = {
            "counters": cls._restore_counters,
            "samples": cls._restore_samples,
            "spans": cls._restore_spans,
        }[section]
        added = restore(bucket["added"])
        removed = restore(bucket["removed"])
        before = restore([item["before"] for item in bucket["changed"]])
        after = restore([item["after"] for item in bucket["changed"]])
        parsed[section] = (added, removed, before, after)
    return (
        parsed["counters"],
        parsed["samples"],
        parsed["spans"],
    )

@staticmethod
def _patch_filtered_view(base_state, pairs):
    # 依据筛选后的 (定位, 快照记录) 对构造“基础状态全集 + 视图子集”：
    # 视图外定位保持内部状态原值，视图内定位随后由应用阶段替换。pairs
    # 中的快照记录需先还原为内部记录形态，因此这里只标记视图内定位，
    # 实际记录在应用阶段从补丁/基础快照记录重新解析。
    kept = dict(base_state)
    view = {}
    for key, _entry in pairs:
        view[key] = None
    return kept, view

@staticmethod
def _patch_record_equal(left, right):
    # 两条已解析的内部记录（计数器为原值、样本为 values 列表、跨度为
    # 记录字典）必须逐项相等；自定义对象比较异常属于补丁与视图不匹配。
    try:
        return left == right
    except Exception as exc:
        raise SnapshotPatchError(
            "patch records cannot be compared: %s" % (exc,)
        )

